abstract class Animal {
    String name;

    public Animal(String name) {
        this.name = name;
    }

    abstract void sound();

    public void eat() {
        System.out.println(name + " is eating...");
    }
}

class Dog extends Animal {
    public Dog(String name) {
        super(name);
    }

    @Override
    public void sound() {
        System.out.println(name + " says: Woof!");
    }
}
